import { defineStore } from "pinia";
import { useReviewsStore } from "./reviews";
import axios from "axios";
export const useProductsStore = defineStore("products", {
  state: () => {
    return {
      loading: false,
      error: null,
      productsList: [],
      topRatingProducts: [],
    };
  },
  getters: {
    topRatingProducts: (state) => {
      return state.productsList.filter((Element) => Element.averageRating >= 4);
    },
    lattestProducts: (state) => {
      return [...state.productsList]
        .sort((a, b) => new Date(b.dateAdded) - new Date(a.dateAdded))
        .slice(0, 5);
    },
    getProductById: (state) => {
      return (targetId) => {
        return state.productsList.find((p) => p.id === targetId);
      };
    },
  },
  actions: {
    async fetchProducts() {
      try {
        this.loading = true;
        this.productsList = [];
        const res = await axios.get("http://localhost:3000/products");
        if (res.data && Array.isArray(res.data)) {
          this.productsList = res.data;
          console.log(`تم جلب ${res.data.length} منتج`);
        } else {
          throw new Error("بيانات غير صالحة من السيرفر");
        }
        console.log(this.productsList[0].name);
      } catch (error) {
        this.error = error.message || "حدث خطأ في جلب البيانات";
        console.error("خطأ في fetchProducts:");
      } finally {
        this.loading = false;
      }
    },
    async patchproductsRating(id) {
      try {
        // جلب التقييمات من الـ store (يجب أن تكون محدثة)
        const reviewsStore = useReviewsStore();
        const productReviews = reviewsStore.reviewsList.filter(
          (r) => r.productId === id
        );

        if (productReviews.length === 0) {
          return; // لا توجد تقييمات
        }

        // حساب المتوسط
        const total = productReviews.reduce(
          (sum, review) => sum + review.rating,
          0
        );
        const average = total / productReviews.length;

        // تحديث في السيرفر
        await axios.patch(`http://localhost:3000/products/${id}`, {
          averageRating: parseFloat(average.toFixed(2)),
        });

        // تحديث محلي
        const index = this.productsList.findIndex((p) => p.id === id);
        if (index !== -1) {
          this.productsList[index].averageRating = average;
        }
      } catch (error) {
        console.error("Error updating product rating:", error);
      }
    },
  },
});
