<template>
  <nav class="navbar navbar-expand-lg bg-body-tertiary">
    <div class="container-fluid">
      <div class="d-flex gap-1 pe-5">
        <a class="navbar-brand" href="#">Shopping Center</a>
        <router-link to="/cart" custom v-slot="{ href, navigate }">
          <div
            :data-cart="cart.bill.length"
            :class="[
              'cart-icon',
              'd-flex',
              'justify-content-center',
              'align-items-center',
              { 'show-notify': cart.bill.length > 0 },
            ]"
          >
            <i
              :href="href"
              @click="navigate"
              role="button"
              class="bi bi-cart"
            ></i>
          </div>
        </router-link>
        <div class="dropdown">
          <a
            class="btn dropdown-toggle"
            href="#"
            role="button"
            data-bs-toggle="dropdown"
            aria-expanded="false"
          >
            {{ tm("header.language") }}
          </a>

          <ul class="dropdown-menu">
            <li>
              <a
                @click.prevent="changeLang('en')"
                class="dropdown-item"
                href="#"
                >{{ tm("header.english") }}</a
              >
            </li>
            <li>
              <a
                @click.prevent="changeLang('ar')"
                class="dropdown-item"
                href="#"
                >{{ tm("header.arabic") }}</a
              >
            </li>
          </ul>
        </div>

        <div class="dropdown">
          <a
            class="btn dropdown-toggle"
            href="#"
            role="button"
            data-bs-toggle="dropdown"
            aria-expanded="false"
          >
            {{ tm("header.profile") }}
          </a>

          <ul class="dropdown-menu">
            <li>
              <a
                @click.prevent="headToProfilePage('ProfileUser')"
                class="dropdown-item"
                href="#"
                >{{ tm("header.profile") }}</a
              >
            </li>
            <li>
              <a
                @click.prevent="headToProfilePage('LogForm')"
                class="dropdown-item"
                href="#"
                >{{ tm("header.login") }}</a
              >
            </li>
            <li>
              <a
                @click.prevent="headToProfilePage('SignForm')"
                class="dropdown-item"
                href="#"
                >{{ tm("header.signin") }}</a
              >
            </li>
          </ul>
        </div>
      </div>

      <button
        class="navbar-toggler"
        type="button"
        data-bs-toggle="collapse"
        data-bs-target="#navbarText"
        aria-controls="navbarText"
        aria-expanded="false"
        aria-label="Toggle navigation"
      >
        <span class="navbar-toggler-icon"></span>
      </button>

      <div class="collapse navbar-collapse" id="navbarText">
        <ul class="navbar-nav me-auto mb-2 mb-lg-0">
          <router-link custom v-slot="{ navigate, isActive, href }" to="/">
            <li class="nav-item">
              <a
                :class="['nav-link', { active: isActive }]"
                aria-current="page"
                :href="href"
                @click="navigate"
                >{{ tm("header.home") }}</a
              >
            </li>
          </router-link>
          <router-link
            custom
            v-slot="{ navigate, isActive, href }"
            to="/products"
          >
            <li class="nav-item">
              <a
                :class="['nav-link', { active: isActive }]"
                aria-current="page"
                :href="href"
                @click="navigate"
                >{{ tm("header.products") }}</a
              >
            </li>
          </router-link>
        </ul>
      </div>
    </div>
  </nav>
</template>

<script setup>
import router from "@/router";
import { useUsersStore } from "@/stores/users";
const users = useUsersStore();
import { useI18n } from "vue-i18n";
const { locale, tm } = useI18n();
import { useCartStore } from "@/stores/cart";
// import { ref } from "vue";
const cart = useCartStore();
// const cartIconElement = ref(null);
function changeLang(lang) {
  locale.value = lang;
  localStorage.setItem("lang", lang);
  document.dir = lang === "ar" ? "rtl" : "ltr";
}

function headToProfilePage(pageName) {
  if (pageName === "ProfileUser") {
    if (users.userLoginStatus) {
      users.switchPage(pageName);
      router.push("/profile");
    } else {
      users.switchPage("SignForm");
      router.push("/profile");
    }
  } else {
    users.switchPage(pageName);
    router.push("/profile");
  }
}
</script>
